		void Tariffs(int day, int month, int year, bool isXLSCheckRequired = false)
		{
			var publicationDate = new DateTime(year, month, day);
			var inputConfigPath = string.Format(CultureInfo.CurrentCulture, @"Res\Tariffs\{0}\Tariffs_{0}Configuration.xml", year);
			var outputDirPath = Path.Combine(TestHelper.BaseTestFilePath, @"Tariffs\Output\Y" + year);
			var outputDirInfo = new DirectoryInfo(outputDirPath);
			if (outputDirInfo.Exists)
			{
				foreach (var file in outputDirInfo.GetFiles())
				{
					file.Delete();
				}
			}

			var expectedOutputFiles = new string[]
			{
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_0.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_1.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_2.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_3.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_4.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_5.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_6.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_7.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_8.xml", year)),
				TestHelper.ReadManifestResourceContent(string.Format(CultureInfo.CurrentCulture, "CargoWise.RefDbRepo.KRReferenceData.Test.TestFiles.Tariffs.Output.Y{0}.RefCusTariff_HSN_{0}_9.xml", year))
			};

			
			var outputFileCommonPath = Path.Combine(TestHelper.BaseTestFilePath, string.Format(CultureInfo.CurrentCulture, @"Tariffs\Output\Y{0}\RefCusTariff_HSN.xml", year));
			var inputDataPathXlsx = Path.Combine(TestHelper.BaseTestFilePath, string.Format(CultureInfo.CurrentCulture, @"Tariffs\Input\{0}\Tariffs_{0}DataFile_Sample.xlsx", year));
			new TariffParserForTest(inputConfigPath, inputDataPathXlsx).ConvertToXMLFile(outputFileCommonPath, publicationDate);
			for (var i = 0; i < 10; i++)
			{
				Assert.That(File.ReadAllText(outputDirPath + string.Format(CultureInfo.CurrentCulture, @"\RefCusTariff_HSN_{0}_{1}.xml", year, i)), Is.EqualTo(expectedOutputFiles[i]));
			}

			if (isXLSCheckRequired)
			{
				var inputDataPathXls = Path.Combine(TestHelper.BaseTestFilePath, string.Format(CultureInfo.CurrentCulture, @"Tariffs\Input\{0}\Tariffs_{0}DataFile_Sample.xls", year));
				new TariffParserForTest(inputConfigPath, inputDataPathXls).ConvertToXMLFile(outputFileCommonPath, publicationDate);
				for (var i = 0; i < 10; i++)
				{
					Assert.That(File.ReadAllText(outputDirPath + string.Format(CultureInfo.CurrentCulture, @"\RefCusTariff_HSN_{0}_{1}.xml", year, i)), Is.EqualTo(expectedOutputFiles[i]));
				}
			}
		}
	}

	class TariffParserForTest : TariffParser
	{
		public TariffParserForTest(string configFilePath, string dataFilePath) : base(configFilePath, dataFilePath) { }
		protected override TariffAdditionalDataUpdater AdditionalDataUpdater => new TariffAdditionalDataUpdaterForTest();
	}

